#!/usr/bin/env node
// Build-artifact freshness.
//
// Three standalone HTML files ship in this repository as single-file downloads.
// Each is generated by build-demo.js from the tested modules, and each carries a
// banner saying "GENERATED FILE — do not edit". Nothing enforced it.
//
// The full assessment of v3.46.2 found the predictable consequence:
// cathedral-unified-2-standalone.html was not reproducible from its sources.
// Commit 1fd4560 ("standalones rebuilt") had hand-edited the page's UI copy and
// not re-run the build, so the file shipped an inlined progression.js one commit
// behind the module. That instance was comment-only and behaviourally inert — but
// nothing about the failure mode was specific to comments, and nothing would have
// caught it if the stale copy had been code.
//
// This runner rebuilds every standalone into memory and compares byte-for-byte
// against what is committed. It writes nothing. A drifted artifact fails the
// suite with the exact command that fixes it.

const fs = require('fs');
const path = require('path');
const dir = __dirname;

// The build map, mirrored from build-demo.js. Kept explicit rather than imported
// so that deleting a build target there is itself a visible diff here.
const BUILDS = [
    { demo: 'relational-demo.html',
      cores: ['relational-core.js', 'relational-memory.js', 'relational-calibration.js'],
      out: 'relational-demo-standalone.html' },
    { demo: 'cathedral-demo.html',
      cores: ['cathedral-core.js', 'feedback-generator.js'],
      out: 'cathedral-demo-standalone.html' },
    { demo: 'cathedral-unified-2.html',
      cores: ['cathedral-core.js', 'relational-core.js', 'relational-memory.js',
              'relational-calibration.js', 'sovereignty-detector.js', 'feedback-generator.js',
              'verdict-memory.js', 'progression.js'],
      out: 'cathedral-unified-2-standalone.html' }
];

// Byte-identical reimplementation of build-demo.js's transform.
function render(demoFile, coreFiles) {
    let html = fs.readFileSync(path.join(dir, demoFile), 'utf8');
    for (const coreFile of coreFiles) {
        const core = fs.readFileSync(path.join(dir, coreFile), 'utf8');
        if (core.includes('</script>')) throw new Error(coreFile + ' contains "</script>"');
        const tag = '<script src="' + coreFile + '"></script>';
        if (!html.includes(tag)) throw new Error(demoFile + ' is missing script tag: ' + tag);
        html = html.replace(tag, () =>
            '<script>\n/* === inlined ' + coreFile + ' (generated) === */\n' + core + '\n</script>');
    }
    const banner = '<!--\n  GENERATED FILE — do not edit.\n' +
        '  Built from ' + demoFile + ' + ' + coreFiles.join(' + ') + ' by build-demo.js.\n' +
        '  Regenerate with: npm run build:demo\n-->\n';
    return banner + html;
}

function firstDifference(a, b) {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) if (a[i] !== b[i]) {
        const line = a.slice(0, i).split('\n').length;
        return { line, committed: a.slice(i, i + 70).split('\n')[0], rebuilt: b.slice(i, i + 70).split('\n')[0] };
    }
    return { line: a.slice(0, n).split('\n').length, committed: '(ends here)', rebuilt: '(longer)' };
}

let passed = 0, failed = 0;
console.log('═'.repeat(63));
console.log('BUILD ARTIFACTS — standalones reproducible from their sources');
console.log('═'.repeat(63));

for (const b of BUILDS) {
    let ok = false, detail = '';
    try {
        const committed = fs.readFileSync(path.join(dir, b.out), 'utf8');
        const rebuilt = render(b.demo, b.cores);
        ok = committed === rebuilt;
        if (!ok) {
            const d = firstDifference(committed, rebuilt);
            detail = '\n    first difference at line ' + d.line +
                     '\n      committed: ' + d.committed +
                     '\n      rebuilt:   ' + d.rebuilt +
                     '\n    fix: npm run build:demo';
        }
    } catch (e) {
        detail = ' — threw: ' + e.message;
    }
    console.log(`\n${ok ? '✓' : '✗'} ${b.out} matches a fresh build${detail}`);
    ok ? passed++ : failed++;
}

console.log('\n' + '═'.repeat(63));
console.log(`SUMMARY: ${passed} passed, ${failed} failed of ${BUILDS.length}`);
console.log('═'.repeat(63));
process.exit(failed === 0 ? 0 : 1);
